css:
/* EFRIS Tax Invoice — table layout only (no flexbox) so wkhtmltopdf renders it the same as the browser. */
.efx { font-family: Arial, Helvetica, sans-serif; font-size: 11px; color: #222; }
.efx table { width: 100%; border-collapse: collapse; }
.efx td, .efx th { vertical-align: top; }
.efx-mono { font-family: "Courier New", monospace; word-break: break-all; }
.efx-muted { font-size: 9.5px; color: #777; }
.efx-sec-title { font-size: 9.5px; font-weight: bold; text-transform: uppercase; letter-spacing: .6px; color: #1e3a5f; margin-bottom: 4px; }

.efx-warn { border: 2px solid #c0392b; color: #c0392b; font-weight: bold; text-align: center; padding: 6px; margin-bottom: 10px; }

.efx-head { border-bottom: 3px solid #1e3a5f; margin-bottom: 10px; }
.efx-head td { padding-bottom: 8px; line-height: 1.5; }
.efx-logo { max-height: 60px; max-width: 160px; display: block; margin-bottom: 4px; }
.efx-seller-name { font-size: 16px; font-weight: bold; color: #1e3a5f; text-transform: uppercase; }
.efx-title-cell { width: 34%; text-align: right; vertical-align: bottom !important; }
.efx-title { font-size: 20px; font-weight: bold; color: #1e3a5f; letter-spacing: 1px; }
.efx-sub { font-size: 10px; color: #777; }

.efx-ura { border: 1.5px solid #1e3a5f; margin-bottom: 10px; page-break-inside: avoid; }
.efx-ura-fields { padding: 8px 10px; }
.efx-kv th { text-align: left; font-weight: bold; color: #555; width: 42%; padding: 3px 6px 3px 0; border-bottom: 1px dotted #ccd; }
.efx-kv td { padding: 3px 0; border-bottom: 1px dotted #ccd; }
.efx-big { font-size: 13px; font-weight: bold; color: #000; }
.efx-qr-cell { width: 150px; text-align: center; padding: 8px; border-left: 1px solid #ccd; vertical-align: middle !important; }
.efx-qr { width: 130px; height: 130px; display: block; margin: 0 auto; }
.efx-qr-hint { font-size: 9px; color: #555; margin-top: 3px; }

.efx-buyer { margin-bottom: 10px; }
.efx-buyer td { line-height: 1.5; }
.efx-buyer-name { font-size: 12px; font-weight: bold; }
.efx-buyer-right { width: 34%; text-align: right; }

.efx-items { margin-bottom: 8px; }
.efx-items thead th { background: #1e3a5f; color: #fff; font-size: 10px; padding: 6px; text-align: left; }
.efx-items tbody td { padding: 5px 6px; border-bottom: 1px solid #e3e8ef; }
.efx-items .r { text-align: right; }
.efx-items .c { text-align: center; }

.efx-bottom { page-break-inside: avoid; }
.efx-words { padding-right: 14px; }
.efx-totals-cell { width: 42%; }
.efx-totals th { text-align: left; font-weight: normal; padding: 4px 8px; background: #f4f7fb; border-bottom: 1px solid #e3e8ef; }
.efx-totals td { text-align: right; font-weight: bold; padding: 4px 8px; background: #f4f7fb; border-bottom: 1px solid #e3e8ef; }
.efx-totals .efx-grand th, .efx-totals .efx-grand td { background: #1e3a5f; color: #fff; font-size: 12px; font-weight: bold; }

.efx-foot { margin-top: 14px; padding-top: 8px; border-top: 1px dashed #bbb; font-size: 9.5px; color: #555; text-align: center; line-height: 1.6; }
.efx-url { font-size: 8.5px; color: #1e3a5f; }
